package com.alpharip.staffmod.BuildTimelapse.ui; import com.alpharip.staffmod.BuildTimelapse.core.BuildTimelapseController; public final class StudioController {private final BuildTimelapseController c;private final StudioScreenModel m;public StudioController(BuildTimelapseController c,StudioScreenModel m){if(c==null||m==null)throw new IllegalArgumentException();this.c=c;this.m=m;}public void start(){c.start();m.setStatus("Recording");}public void pause(){c.pause();m.setStatus("Paused");}public void resume(){c.resume();m.setStatus("Recording");}public void stop(){c.stop();m.setStatus("Stopped");}public void save()throws java.io.IOException{c.save();m.setStatus("Saved");}}
